mission_data:
  TSN Command Systems Version {{ g.version }}, compiled at {{ g.time }}. Maps:{% for map in g.data.get("maps", []) %} {{ map }}{% endfor %} - Extensions:{% for script in g.data.get("extensions", []) %} {{ script }}{% endfor %}
{% include 'Elements.xml' %}
{% include 'Legacy Maps/LegacyMapSystems.jinja' %}
{% include 'Custom Config.xml' %}
{% include 'Spawn.xml' %}
{% include 'Fleets/FleetSystem.xml' %}
{% include 'Subsystems/Subsystems.xml' %}
{% include 'GM/GMTools.xml' %}

{% import 'ModuleUtils.xml' as modutil %}
{% import 'Utils.xml' as util %}
{% for ship in util.shipConfigs %}
  {% for module in g.data.get("modules", {}).get("ship" + ship.id, []) %}
      {% import 'Modules/' + module + '.xml' as mod %}
      {{ mod.render(ship, modutil) }}
  {% endfor %}
{% endfor %}
{% for map in g.data.get("maps", []) %}
  {% include 'Generated Maps/' + map + '.xml' %}
{% endfor %}
{% for extension in g.data.get("extensions", []) %}
  {% include 'Extensions/' + extension + '.xml' %}
{% endfor %}

{# Below are core files that track information from other files/modules and therefore need to come last. #}
{# Their relative order is also sensitive; handle with care. #}
{% include 'Fleets/Destroy.xml' %}
{% include 'MapSystem/MapSystem.xml' %}
{% include 'PlayerTracking.xml' %}
{% include 'Comms.xml' %}
{% include 'GM Console.xml' %}
{% include 'GM Menus.xml' %}
{% include 'Start.xml' %}
